/* global console, document, Excel, Office */

Office.onReady((info) => {
  if (info.host === Office.HostType.Excel) {
    document.getElementById("sideload-msg").style.display = "none";
    document.getElementById("app-body").style.display = "flex";
    document.getElementById("run").onclick = run;
    document.getElementById("extract-btn")?.addEventListener("click", extractHyperlinks);
    document.getElementById("export-json")?.addEventListener("click", exportRangeToJSON);
  }
});

export async function run() {
  try {
    await Excel.run(async (context) => {
      /**
       * Insert your Excel code here
       */
      const range = context.workbook.getSelectedRange();

      // Read the range address
      range.load("address");

      // Update the fill color
      range.format.fill.color = "yellow";

      await context.sync();
      console.log(`The range address was ${range.address}.`);
    });
  } catch (error) {
    console.error(error);
  }
}

async function extractHyperlinks() {
  console.log('extract start222')
  try {
    await Excel.run(async (context) => {
      const sheet = context.workbook.worksheets.getActiveWorksheet();

      const range = sheet.getRange("A2:A1000");
      range.load("values");
      await context.sync();

      const values = range.values.map(r => r[0]);
      const lastRow = values.filter(v => v !== null && v !== "").length;

      const hyperlinks: string[] = [];

      // 각 셀을 개별로 가져와서 로드
      for (let i = 0; i < lastRow ; i++) {
        const cell = sheet.getRange(`A${i + 2}`); // A2부터 시작
        cell.load("hyperlink");
        await context.sync(); // ⬅️ 개별적으로 sync 해서 안전하게 로딩

        const hyperlink = cell.hyperlink;
        hyperlinks.push(hyperlink?.address ?? "");
      }

      // P열에 결과 작성
      const resultRange = sheet.getRange(`P2:P${lastRow}`);
      resultRange.values = hyperlinks.map(link => [link]);

      await context.sync();

      const statusElem = document.getElementById("status");
      if (statusElem) {
        statusElem.textContent = "✅ 하이퍼링크 추출 완료!";
      }
    });
    
  } catch (error) {
    console.error(error);
    document.getElementById("status")!.textContent = `❌ 오류 발생: ${error}`;
  }
}

async function exportRangeToJSON() {
  const status = document.getElementById("export-status");

  try {
    await Excel.run(async (context) => {
      const sheet = context.workbook.worksheets.getActiveWorksheet();

      // A1부터 시작하는 사용된 범위
      const usedRange = sheet.getUsedRange();
      usedRange.load(["values", "rowCount", "columnCount"]);
      await context.sync();

      const values = usedRange.values;
      const rowCount = usedRange.rowCount;
      const colCount = usedRange.columnCount;

      if (rowCount < 2) throw new Error("데이터가 부족합니다.");

      const keys = values[0]; // 첫 번째 행 → 키
      const data = [];

      for (let i = 1; i < rowCount; i++) {
        const rowObj: { [key: string]: string } = {};
        for (let j = 0; j < colCount; j++) {
          rowObj[keys[j]] = String(values[i][j]);
        }
        data.push(rowObj);
      }

      const jsonStr = JSON.stringify(data, null, 2);

      // JSON Blob 다운로드
      const blob = new Blob([jsonStr], { type: "application/json;charset=utf-8" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = "data.json";
      a.click();
      URL.revokeObjectURL(url);

      if (status) status.textContent = "✅ JSON 파일 다운로드 완료!";
    });
  } catch (error) {
    console.error(error);
    if (status) status.textContent = `❌ 오류: ${error}`;
  }
}